"""Read-only access to bounded, attributable public search results."""

import json
from urllib.parse import urlencode
from urllib.request import Request, urlopen

_WIKIPEDIA = "https://pt.wikipedia.org"
_MAX_BYTES = 256 * 1024


def search_wikipedia(term, *, timeout=8, opener=None):
    """Return searchable page identities generated by the Portuguese MediaWiki API."""
    if not isinstance(term, str) or not 1 <= len(term.strip()) <= 300:
        raise ValueError("Termo de pesquisa inválido.")
    query = urlencode({"action": "query", "list": "search", "srsearch": term.strip(),
                       "srnamespace": 0, "srlimit": 5, "format": "json", "formatversion": 2})
    request = Request(f"{_WIKIPEDIA}/w/api.php?{query}", headers={
        "Accept": "application/json", "User-Agent": "BRAINNET/9.8 (local user search)",
    })
    with (opener or urlopen)(request, timeout=timeout) as response:
        data = response.read(_MAX_BYTES + 1)
    if len(data) > _MAX_BYTES:
        raise ValueError("Resposta da fonte acima do limite.")
    payload = json.loads(data)
    query_data = payload.get("query") if isinstance(payload, dict) else None
    rows = query_data.get("search") if isinstance(query_data, dict) else None
    if not isinstance(rows, list):
        raise ValueError("Resposta da fonte sem resultados interpretáveis.")
    results = []
    for row in rows[:5]:
        if not isinstance(row, dict):
            continue
        page_id, title = row.get("pageid"), row.get("title")
        if type(page_id) is int and page_id > 0 and isinstance(title, str) and title.strip():
            results.append({"title": " ".join(title.split())[:220], "page_id": page_id,
                            "url": f"{_WIKIPEDIA}/?curid={page_id}", "source": "wikipedia.pt"})
    return results
